Subroutine Suspendable Ofrecer(oferta As Channel<Integer>, precio As Integer)
  Define aceptado As Boolean <- Await oferta.send(precio);
  If Not aceptado Then
    Write "La oferta llegó tarde";
  EndIf
EndSubroutine

Algorithm PrimeraOferta
  Define norte As Channel<Integer> <- channel(1);
  Define sur As Channel<Integer> <- channel(1);
  Tasks
    Spawn Ofrecer(norte, 12);
    Spawn Ofrecer(sur, 10);
    Select
      Receive deNorte From norte:
        Switch deNorte Do
          Some(precio): Write "Norte ofrece ", precio;
          None: Write "Norte no ofrece";
        EndSwitch
      Receive deSur From sur:
        Switch deSur Do
          Some(precio): Write "Sur ofrece ", precio;
          None: Write "Sur no ofrece";
        EndSwitch
    EndSelect
  EndTasks
EndAlgorithm

Subroutine Suspendable Consultar(nombre As String, stock As Integer) As Result<Integer, String>
  If stock = 0 Then
    Return Failure(nombre + " no tiene stock");
  EndIf
  Return Success(stock);
EndSubroutine

Algorithm Pedido
  Tasks fallo
    Spawn Consultar("Norte", 0);
    Spawn Consultar("Sur", 5);
    Spawn Consultar("Oeste", 3);
  EndTasks
  Switch fallo Do
    Some(problema):
      Write "Falló: ", problema.first;
      Write "Canceladas: ", problema.cancelled;
    None: Write "Todos confirmaron";
  EndSwitch
EndAlgorithm
